import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk, UsageMetadata} from '../types/ai.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import {ToolRegistry} from './tools/registry.js';
import type {ChatSession} from '../types/session.js';

const SENT_AT = '2026-01-01T00:00:00.000Z';

function createSession(content: string): ChatSession {
  return {
    sessionId: 's1',
    userId: 'u1',
    workspaceId: 'w1',
    entries: [{role: 'user', content, timestamp: SENT_AT}],
  };
}

const scriptedProvider = (rounds: MessageChunk[][]): AIProvider => {
  let round = 0;
  return {
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      for (const chunk of rounds[round++] ?? []) yield chunk;
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
};

const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});

describe('Report usage across every tool round', () => {
  it('A turn driven through two tool rounds reports usage covering every provider call in that turn. ([validated by name](src/orchestration/after-model-response-usage.acceptance.test.ts#L0))', async () => {
    let reportedUsage: UsageMetadata | undefined;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, usage) => {
        reportedUsage = usage;
      },
    };

    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'weather',
        description: 'get weather',
        inputSchema: {type: 'object', required: ['location'], properties: {location: {type: 'string'}}},
      },
      async () => 'sunny in London'
    );

    const orchestrator = createChatOrchestrator(
      scriptedProvider([
        [
          {type: 'tool_use', toolCall: {id: 'c1', name: 'weather', input: {location: 'London'}}},
          {type: 'stop', stopReason: 'tool_use', usage: {inputTokens: 10, outputTokens: 5, totalTokens: 15}},
        ],
        [
          {type: 'tool_use', toolCall: {id: 'c2', name: 'weather', input: {location: 'Paris'}}},
          {type: 'stop', stopReason: 'tool_use', usage: {inputTokens: 12, outputTokens: 6, totalTokens: 18}},
        ],
        [
          {type: 'text', text: 'done'},
          {type: 'stop', stopReason: 'end_turn', usage: {inputTokens: 20, outputTokens: 10, totalTokens: 30}},
        ],
      ]),
      promptBuilder,
      registry,
      {hooks}
    );

    await orchestrator.processMessage(createSession('ask'));

    expect(reportedUsage).toEqual({
      inputTokens: 42,
      outputTokens: 21,
      totalTokens: 63,
    });
  });

  it('A provider that reports no usage on some rounds does not make the total undefined or NaN. ([validated by name](src/orchestration/after-model-response-usage.acceptance.test.ts#L0))', async () => {
    let reportedUsage: UsageMetadata | undefined;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, usage) => {
        reportedUsage = usage;
      },
    };

    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'weather',
        description: 'get weather',
        inputSchema: {type: 'object', required: ['location'], properties: {location: {type: 'string'}}},
      },
      async () => 'sunny in London'
    );

    const orchestrator = createChatOrchestrator(
      scriptedProvider([
        [
          {type: 'tool_use', toolCall: {id: 'c1', name: 'weather', input: {location: 'London'}}},
          {type: 'stop', stopReason: 'tool_use', usage: {inputTokens: 10, outputTokens: 5, totalTokens: 15}},
        ],
        [
          {type: 'tool_use', toolCall: {id: 'c2', name: 'weather', input: {location: 'Paris'}}},
          {type: 'stop', stopReason: 'tool_use'},
        ],
        [
          {type: 'text', text: 'done'},
          {type: 'stop', stopReason: 'end_turn', usage: {inputTokens: 20, outputTokens: 10, totalTokens: 30}},
        ],
      ]),
      promptBuilder,
      registry,
      {hooks}
    );

    await orchestrator.processMessage(createSession('ask'));

    expect(reportedUsage).toEqual({
      inputTokens: 30,
      outputTokens: 15,
      totalTokens: 45,
    });
  });

  it('A turn where nothing reported still reports nothing. ([validated by name](src/orchestration/after-model-response-usage.acceptance.test.ts#L0))', async () => {
    let reportedUsage: UsageMetadata | undefined;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, usage) => {
        reportedUsage = usage;
      },
    };

    const orchestrator = createChatOrchestrator(
      scriptedProvider([
        [
          {type: 'text', text: 'done'},
          {type: 'stop', stopReason: 'end_turn'},
        ],
      ]),
      promptBuilder,
      new ToolRegistry(),
      {hooks}
    );

    await orchestrator.processMessage(createSession('ask'));

    expect(reportedUsage).toBeUndefined();
  });
});

